function validate(input) {
  const [{ NPV = [], Queries = [] }] = input;
  const values = new Set(), lookups = new Set();
  for (const [id, year, npv] of NPV) {
    if (id === null || year === null || npv === null) return 'Every NPV row needs an id, a year and an npv.';
    if (values.has(`${id}/${year}`)) return `(${id}, ${year}) appears twice in NPV.`;
    values.add(`${id}/${year}`);
  }
  for (const [id, year] of Queries) {
    if (id === null || year === null) return 'Every query needs an id and a year.';
    if (lookups.has(`${id}/${year}`)) return `(${id}, ${year}) appears twice in Queries.`;
    lookups.add(`${id}/${year}`);
  }
  return null;
}

