function generate(rand, size) {
  const small = size === 'small';
  const ids = small ? 4 : 100, years = small ? 3 : 30, first = small ? 2018 : 2000;
  const pairs = [];
  for (let id = 1; id <= ids; id++) for (let y = 0; y < years; y++) pairs.push([id, first + y]);
  const sample = count => {
    const pool = pairs.slice();
    for (let i = pool.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [pool[i], pool[j]] = [pool[j], pool[i]]; }
    return pool.slice(0, count);
  };
  const values = [0, 21, 40, 100, 113];
  const NPV = sample(small ? Math.floor(rand() * 9) : 2000).map(([id, year]) => [id, year, small ? values[Math.floor(rand() * values.length)] : Math.floor(rand() * 1000)]);
  const Queries = sample(small ? Math.floor(rand() * 9) : 2000).map(([id, year]) => [id, year]);
  return [{ NPV, Queries }];
}
